import React from 'react';
import './SignUp.css';
import { useNavigate } from 'react-router-dom';
import { useState } from 'react';
import User from '../User.js';
import usersList from '../UsersList.js';
import { checkForm } from './validate.js';




function SignUp() {
    const navigate = useNavigate();

    const [firstName, setFirstName] = useState('');
    const [lastName, setLastName] = useState('');
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [ConfirmedPassword, setConfirmedPassword] = useState('');
    const [picture, setPicture] = useState('');



    const handleCloseClick = () => {
        // Navigate to the login page
        navigate('/');
    };

    const handleSignUpClick = async () => {

        // Check if the form is valid
        const requiredElements = document.querySelectorAll('[required]');
        const isValid = checkForm(requiredElements);

        if (isValid) {
            // Create a new user
            const user = new User(0, firstName, lastName, email, password, picture);


            const users = usersList.getUsers();
            console.log('User information before adding:', user);
            console.log('Users:', users);

            // Add the user to the list of users
            usersList.addUser(user);

            console.log('Users information after adding:', users);


            // Navigate to the login page
            navigate('/');
        }
    };





    


    

    return (
        <form class="SIform" novalidate>
            <button id="close" type="button" class="btn-close" onClick={handleCloseClick} aria-label="Close"></button>
            <div class="headLine">
                <p id="first">Sign Up</p>
                <p id="second">It's quick and easy.</p>
            </div>
            <hr></hr>

            <form class="container text">
                <div class="row">
                    <div class="col">
                        <div class="mb-3">
                            <div class="input-group">
                                <input type="firstName"
                                    class="form-control"
                                    id="InputFirstName"
                                    placeholder="First name"
                                    aria-describedby="inputGroupPrepend"
                                    value={firstName}
                                    onChange={(e) => setFirstName(e.target.value)}
                                    required>
                                </input>
                            </div>
                        </div>
                    </div>
                    <div class="col">
                        <div class="mb-3">
                            <div class="input-group">
                                <input type="lastName"
                                    class="form-control"
                                    id="InputLastName"
                                    placeholder="Last name"
                                    aria-describedby="inputGroupPrepend"
                                    value={lastName}
                                    onChange={(e) => setLastName(e.target.value)}
                                    required>
                                </input>
                            </div>
                        </div>
                    </div>
                </div>


                <div class="mb-3">
                    <div class="input-group">
                        <input type="EmailOrNumber"
                            class="form-control"
                            id="InputEmail"
                            placeholder="Mobile number or email"
                            aria-describedby="inputGroupPrepend"
                            value={email}
                            onChange={(e) => setEmail(e.target.value)}
                            required>
                        </input>
                    </div>
                </div>
                <div class="mb-3">
                    <input type="password" class="form-control" id="InputPassword" placeholder="New Password"
                        aria-describedby="inputGroupPrepend"
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                        required>
                    </input>
                </div>

                <div class="mb-3">
                    <input type="password" class="form-control" id="ConfirmedPassword" placeholder="Confirm Password"
                        aria-describedby="inputGroupPrepend"
                        value={ConfirmedPassword}
                        onChange={(e) => setConfirmedPassword(e.target.value)}
                        required>
                    </input>
                </div>
                <p>* first name and last name must contain only letters</p>
                <p>* password must contain at least 8 characters, including a letter, number and a special character</p>
                
            </form>



            <p>picture</p>
            <div class="mb-3">
                <input class="form-control" type="file" id="formFile"
                    aria-describedby="inputGroupPrepend"
                    value={picture}
                    onChange={(e) => setPicture(e.target.value)}
                    required></input>
            </div>

            <div id="signUpBtn">
                <button type="submit" class="btn btn-primary" onClick={handleSignUpClick}>Sign Up</button>
            </div>

        </form>


    );
}

                export default SignUp;
